// Block (composition) — a site's global navigation bar (GNB): brand, primary destinations, an
// optional search, and account actions, on a SiteHeader that spans the window and sticks while the
// page scrolls. Posture: page chrome; place it ABOVE the page grid, not inside it, since the
// SiteHeader frame already follows the grid's margin and cap.
import { useState, type ReactNode, type Ref } from "react";
import { Button } from "../components/Button";
import { Link } from "../components/Link";
import { Menu, MenuItem } from "../components/Menu";
import { NavItem } from "../components/NavItem";
import { SiteHeader } from "../components/SiteHeader";
import { Stack } from "../layouts/Stack";
import "./Navbar.css";

export interface NavbarLink {
  label: string;
  /** Destination. Omit when `items` makes this entry a dropdown. */
  href?: string;
  /** Marks the page being viewed: aria-current="page" and the current highlight. */
  isCurrent?: boolean;
  /** Sub-destinations, shown in a menu the entry opens. */
  items?: { label: string; href: string }[];
  /**
   * A mark raised over the entry's top end, such as `<Badge variant="tonal">NEW</Badge>` for a new
   * destination. It sits beside the link rather than inside it, so a screen reader reads it right
   * after the link's name.
   */
  badge?: ReactNode;
}

export interface NavbarProps {
  /** Brand mark or name shown at the start of the navigation. */
  brand: ReactNode;
  /** A narrower mark shown in `brand`'s place below the medium step, where a phone bar holds the
   *  symbol alone (the wordmark returns from the medium step up). */
  brandCompact?: ReactNode;
  /** Primary navigation destinations. */
  links?: NavbarLink[];
  /** Secondary destinations (sign in, help, order status) in a small row above the bar, the two-tier
      GNB. Shown from the medium step; on a phone they belong in the menu the menu button opens. */
  utilityLinks?: { label: string; href: string }[];
  /** A search control (a SearchField, or a button opening a CommandMenu), shown from the large step. */
  search?: ReactNode;
  /** Account or utility actions shown at the end. */
  actions?: ReactNode;
  /**
   * Called when the mobile menu button is pressed. The button is drawn only with it, below the
   * medium step: leave it out where a phone reaches the destinations another way (a BottomNav).
   */
  onMenuPress?: () => void;
  /**
   * The step from which the bar shows its destinations and utility row instead of the menu button,
   * and the full brand instead of `brandCompact`. A product whose phone layout runs up to a tablet
   * switches at `large`, matching its AppShell's `breakpoint`.
   *
   * @default "medium"
   */
  breakpoint?: "medium" | "large";
  /** Keeps the bar at the top while the page scrolls. */
  isSticky?: boolean;
  className?: string;
  ref?: Ref<HTMLElement>;
}

// A dropdown entry: a NavItem in button mode opens a Menu of links, its chevron turning with the menu.
function NavbarMenu({ link }: { link: NavbarLink & { items: { label: string; href: string }[] } }) {
  const [isOpen, setOpen] = useState(false);
  return (
    <Menu
      aria-label={link.label}
      isOpen={isOpen}
      onOpenChange={setOpen}
      trigger={
        <NavItem variant="contained" hasChevron isExpanded={isOpen} isCurrent={link.isCurrent}>
          {link.label}
        </NavItem>
      }
    >
      {link.items.map((item) => (
        <MenuItem key={item.href} href={item.href}>
          {item.label}
        </MenuItem>
      ))}
    </Menu>
  );
}

export function Navbar({
  brand,
  brandCompact,
  breakpoint = "medium",
  links = [],
  utilityLinks = [],
  search,
  actions,
  onMenuPress,
  isSticky = true,
  className,
  ref,
}: NavbarProps) {
  return (
    <SiteHeader isSticky={isSticky} ref={ref} className={className ? `sd-navbar ${className}` : "sd-navbar"}>
      {utilityLinks.length > 0 && (
        <nav aria-label="Utility navigation" className="sd-navbar__utility" data-breakpoint={breakpoint}>
          <Stack as="ul" direction="row" justify="end" align="center" gap="medium" className="sd-navbar__utility-links">
            {utilityLinks.map((link, index) => (
              <li key={`${link.label}-${index}`}>
                {/* One rung below the primary destinations it sits above (naming-convention.md § CONTRASTIVE):
                    secondary links, read after the bar. */}
                <Link href={link.href} variant="quiet" className="sd-type-label-small">
                  {link.label}
                </Link>
              </li>
            ))}
          </Stack>
        </nav>
      )}
      <Stack
        as="nav"
        direction="row"
        justify="between"
        align="center"
        gap="x-large"
        aria-label="Primary navigation"
        className="sd-navbar__bar"
      >
        <div className="sd-navbar__brand">
          <div className="sd-navbar__brand-full" data-breakpoint={breakpoint} data-has-compact={brandCompact ? "" : undefined}>{brand}</div>
          {brandCompact && <div className="sd-navbar__brand-compact" data-breakpoint={breakpoint}>{brandCompact}</div>}
        </div>
        {links.length > 0 && (
          <Stack as="ul" direction="row" align="center" gap="x-small" className="sd-navbar__links" data-breakpoint={breakpoint}>
            {links.map((link, index) => (
              <li key={`${link.label}-${index}`} className="sd-navbar__link-item">
                {link.items?.length ? (
                  <NavbarMenu link={{ ...link, items: link.items }} />
                ) : (
                  <NavItem variant="contained" href={link.href ?? "#"} isCurrent={link.isCurrent}>
                    {link.label}
                  </NavItem>
                )}
                {link.badge != null && <span className="sd-navbar__link-badge">{link.badge}</span>}
              </li>
            ))}
          </Stack>
        )}
        {/* Drawn only with something in it: an empty end slot still takes a place in the bar, which
            centred the destinations between it and the brand instead of ending them at the edge. */}
        {(search || actions || onMenuPress) && (
        <Stack direction="row" align="center" justify="end" gap="x-small" className="sd-navbar__actions">
          {search && <div className="sd-navbar__search">{search}</div>}
          {actions}
          {onMenuPress && (
            <Button
              variant="secondary"
              size="small"
              onPress={onMenuPress}
              aria-label="Open navigation menu"
              className="sd-navbar__menu"
              data-breakpoint={breakpoint}
            >
              Menu
            </Button>
          )}
        </Stack>
        )}
      </Stack>
    </SiteHeader>
  );
}

/* Navbar.css — .sd-navbar (Block)
   Arrangement only: the SiteHeader owns the bar's fill, edge and frame; this places the brand, the
   destinations, search and actions inside it, and swaps the inline destinations for the menu button
   below the medium step (mobile-first, ADR-0014). */

/* A bar takes the block inset the AppShell header takes (`space.medium`), so a page's top bar sits
   the same distance from the top edge whichever frame holds it. */
.sd-navbar__bar {
  padding-block: var(--sd-space-medium);
}

.sd-navbar__brand {
  flex-shrink: 0;
}

/* With a compact mark, a phone shows it in the brand's place; the full brand returns from medium up. */
.sd-navbar__brand-full[data-has-compact] {
  display: none;
}

/* Hidden on a phone, where the menu button stands in for them. */
.sd-navbar__links,
.sd-navbar__search,
.sd-navbar__utility {
  display: none;
}

/* Search waits for the large step: at medium the destinations, a search field and the actions do not
   fit one row, and the call to action wrapped onto two lines (measured at 768). */

/* The utility row sits above the bar with no edge between them: the smaller type and the end
   alignment tell it apart, and its links end on the actions' edge below. */
.sd-navbar__utility {
  padding-block-start: var(--sd-space-x-small);
}

.sd-navbar__utility-links {
  margin: 0;
  padding: 0;
  list-style: none;
}

.sd-navbar__links {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* A destination's badge is raised over the entry's top end, clear of the label it marks. */
.sd-navbar__link-item {
  position: relative;
}

.sd-navbar__link-badge {
  position: absolute;
  inset-block-start: 0;
  /* past the entry's end, by inline offset rather than a translate so it mirrors in right-to-left */
  inset-inline-end: calc(-1 * var(--sd-space-x-small));
  translate: 0 -50%;
  pointer-events: none;
}

@media (min-width: 768px) {
  .sd-navbar__links:not([data-breakpoint="large"]),
  .sd-navbar__utility:not([data-breakpoint="large"]) {
    display: flex;
  }

  .sd-navbar__brand-full[data-has-compact]:not([data-breakpoint="large"]) {
    display: block;
  }

  .sd-navbar__brand-compact:not([data-breakpoint="large"]) {
    display: none;
  }

  .sd-navbar__utility:not([data-breakpoint="large"]) {
    justify-content: flex-end;
  }

  .sd-navbar__menu:not([data-breakpoint="large"]) {
    display: none;
  }
}

/* The same wide layout from the large step instead, where a product switches there (`breakpoint="large"`).
   Generated as a copy of the block above with the opposite qualifier, so the two can never disagree. */
@media (min-width: 1024px) {
  .sd-navbar__links[data-breakpoint="large"],
  .sd-navbar__utility[data-breakpoint="large"] {
    display: flex;
  }

  .sd-navbar__brand-full[data-has-compact][data-breakpoint="large"] {
    display: block;
  }

  .sd-navbar__brand-compact[data-breakpoint="large"] {
    display: none;
  }

  .sd-navbar__utility[data-breakpoint="large"] {
    justify-content: flex-end;
  }

  .sd-navbar__menu[data-breakpoint="large"] {
    display: none;
  }
}

@media (min-width: 1024px) {
  .sd-navbar__search {
    display: flex;
  }
}
